<script setup>
import {ref} from 'vue'
import {sys,errorText} from '../api/client'
const file=ref(null),busy=ref(false),error=ref(''),report=ref(null)
async function upload(){error.value='';report.value=null;if(!file.value)return error.value='请选择 Excel 文件。';if(file.value.size>5*1024*1024)return error.value='文件不能超过 5MB。';if(!/\.xlsx?$/i.test(file.value.name))return error.value='仅支持 .xls 或 .xlsx 文件。';busy.value=true;try{const data=new FormData();data.append('file',file.value);report.value=await sys('post','/api/sys-user/import',data)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><h1>批量导入学生</h1><p>请先确认班级已创建并启用，再上传学生名单。</p><section class="panel"><h2>准备学生名单</h2><p>第一张工作表的前三列表头必须依次为：<b>学号、姓名、班级编号</b>。每次最多 1000 行，支持 .xls / .xlsx，文件不超过 5MB。</p><table><thead><tr><th>学号</th><th>姓名</th><th>班级编号</th></tr></thead><tbody><tr><td>请填写真实学号</td><td>请填写学生姓名</td><td>请填写已启用的班级编号</td></tr></tbody></table><p class="hint">编号建议设为文本，保留前导零和长学号精度。超过 15 位的数字、公式、布尔值和错误单元格不可导入。新建账号初始密码为 123456。</p><form class="toolbar" @submit.prevent="upload"><input aria-label="选择学生名单" type="file" accept=".xls,.xlsx" :disabled="busy" @change="file=$event.target.files[0]"><button :disabled="busy||!file">{{busy?'正在导入…':'上传并导入'}}</button></form><div v-if="error" class="alert error" role="alert">{{error}}</div></section><section v-if="report" class="panel"><h2>导入结果</h2><div class="stats"><div><b>{{report.total}}</b>处理人数</div><div><b>{{report.successCount}}</b>成功人数</div><div><b>{{report.skippedCount}}</b>跳过人数</div><div><b>{{report.failedCount}}</b>失败人数</div></div><p v-if="!report.details?.length" class="alert success">全部处理成功。</p><div v-else class="table-wrap"><table><thead><tr><th>行号</th><th>学号</th><th>结果</th><th>原因</th></tr></thead><tbody><tr v-for="(r,i) in report.details" :key="i"><td>{{r.rowNumber}}</td><td>{{r.studentId||'—'}}</td><td>{{r.status==='SKIPPED'?'跳过':'失败'}}</td><td>{{r.message}}</td></tr></tbody></table></div></section></template>
